INSERT INTO world.creature_text (CreatureID, GroupID, ID, Text, Type, Language, Probability, Emote, Duration, Sound, BroadcastTextId, TextRange, comment) VALUES
(1853, 0, 0, 'School is in session!', 12, 0, 0, 0, 0, 0, 7145, 0, 'VMaNGOS'),
(2624, 0, 0, 'Oh now you''ve gone and angered me! Time to see the true force of the Stone of Tides!', 12, 0, 0, 0, 0, 0, 1113, 0, 'VMaNGOS'),
(5402, 0, 0, 'I am here!  Come face me, if you dare!', 12, 0, 0, 0, 0, 0, 1905, 0, 'VMaNGOS'),
(6729, 0, 0, 'Aku''mai is dead! At last, I can leave this wretched place.', 12, 0, 0, 0, 0, 0, 2848, 0, 'VMaNGOS'),
(8578, 0, 0, 'You dare! Now feel my wrath, $r.', 12, 0, 0, 0, 0, 0, 4495, 0, 'VMaNGOS'),
(8581, 0, 0, 'Who dares?! I will destroy you!', 12, 0, 0, 0, 0, 0, 4502, 0, 'VMaNGOS'),
(8581, 1, 0, 'Mistress!! They seek to destroy your work!!', 12, 0, 0, 0, 0, 0, 4491, 0, 'VMaNGOS'),
(9453, 0, 0, '$n, you have disturbed me from my rest!', 12, 0, 0, 0, 0, 0, 5463, 0, 'VMaNGOS'),
(10264, 0, 0, 'I am here!  Now, puny little worms, you will pay for your intrusion!', 12, 0, 0, 0, 0, 0, 5547, 0, 'VMaNGOS'),
(10339, 0, 0, 'Taste in my power!', 12, 0, 0, 0, 0, 0, 5726, 0, 'VMaNGOS'),
(10339, 1, 0, '%s is knocked off his drake!', 12, 0, 0, 0, 0, 0, 5711, 0, 'VMaNGOS'),
(10506, 0, 0, '%s lets out a shrill cry.', 12, 0, 0, 0, 0, 0, 5788, 0, 'VMaNGOS'),
(14566, 0, 0, '%s breaks free of its spectral bonds with a tremendous crash of thunder!', 12, 0, 0, 0, 0, 0, 9763, 0, 'VMaNGOS'),
(15341, 0, 0, 'Warriors, Captains, continue the fight! ', 12, 0, 0, 0, 0, 8640, 11434, 0, 'VMaNGOS'),
(15341, 1, 0, '%s becomes enraged!', 12, 0, 0, 0, 0, 0, 2384, 0, 'VMaNGOS'),
(15341, 2, 0, 'Breathe your last!', 12, 0, 0, 0, 0, 8639, 11433, 0, 'VMaNGOS'),
(15341, 3, 0, 'Soon you will know the price of your meddling, mortals... The master is nearly whole... And when he rises, your world will cease.', 12, 0, 0, 0, 0, 0, 11429, 0, 'VMaNGOS'),
(15341, 4, 0, 'Run if you want cowards!  It will do you no good!', 12, 0, 0, 0, 0, 0, 11660, 0, 'VMaNGOS'),
(15554, 0, 0, 'KILL!', 12, 0, 0, 0, 0, 0, 11110, 0, 'VMaNGOS');
